INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>چرا انتخاب درست لوله نخی و تاشو برای مزارع کلیبر حیاتی است؟</h2>\n<p>انتقال آب به روش‌های سنتی مانند کانال‌بندی باز، همواره با چالش‌هایی از جمله تبخیر شدید، نشتی آب و توزیع نامنظم همراه بوده است. لوله‌های نخی و تاشو () راهکاری مدرن و انعطاف‌پذیر هستند که امکان جابجایی آسان، کاهش تلفات آب و مدیریت بهینه منابع آبی را فراهم می‌کنند. در کلیبر و اذربایجان شرقی، شرایط کوهستانی و نوسانات دما بر طراحی سیستم آبیاری تأثیرگذار است. بنابراین، اصول فنی استفاده از این لوله‌ها برای انتقال آب در مناطق با شیب و اختلاف ارتفاع، نیازمند دقت ویژه در انتخاب جنس، سایز و کلاس فشاری است تا با شرایط محیطی سازگار باشند. این سیستم‌ها به عنوان خطوط انتقالی اصلی در بسیاری از مزارع کارآمد عمل می‌کنند و جایگزین مناسبی برای لوله‌های ثابت در مواردی هستند که نیاز به تغییر موقعیت خطوط وجود دارد.</p>\n\n<h3>تعریف لوله نخی و تاشو ()</h3>\n<p>لوله نخی و تاشو، نوعی لوله فلکسیبل (مخروطی) با بدنه مش‌مانندی و پوشش‌های داخلی و خارجی است که قابلیت تا شدن و فشردن برای حمل و ذخیره‌سازی را دارد. این لوله‌ها معمولا دارای بدنه بافته شده هستند که با پوشش‌هایی از جنس پلی‌اورتان یا پلی‌اتیلن پوشانده شده‌اند. ویژگی بارز آن‌ها انعطاف‌پذیری بالا، سبکی نسبی در مقایسه با لوله‌های سخت و قابلیت باز شدن سریع با ورود آب است. این ویژگی‌ها برای جابه‌جایی مکرر خطوط آبیاری در مزارع، به‌ویژه در فصل‌های مختلف سال، بسیار کاربردی هستند. نکته مهم این است که لوله نخی/تاشو خود به عنوان لاین اصلی یا انتقالی عمل می‌کند و می‌تواند نوارهای فرعی را تغذیه کند.</p>\n\n<h2>اصول فنی انتخاب سایز و ضخامت لوله برای انتقال آب</h2>\n<p>انتخاب صحیح سایز و ضخامت لوله، مستقیماً بر افت فشار، سرعت جریان و عمر مفید سیستم تأثیر می‌گذارد. دو پارامتر اصلی در این فرآیند، قطر داخلی (ID) و ضخامت جداره (W) هستند. انتخاب نادرست ممکن است منجر به افت فشار غیرقابل قبول در انتهای خط یا در معرض ماندن لوله در برابر فشار بیش از حد تحمل شود. بنابراین، محاسبات اولیه باید بر اساس دبی مورد نیاز و طول مسیر انجام شود.</p>\n<ul>\n<li><strong>قطر داخلی (ID):</strong> قطر لوله باید بر اساس دبی کل جریان محاسبه شود. اگر قطر کمتر از حد مطلوب باشد، سرعت جریان افزایش می‌یابد که باعث افت فشار و سایش بیشتر می‌شود. در مقابل، اگر قطر بسیار بزرگ‌تر از نیاز باشد، سرعت جریان کاهش می‌یابد و در مسیرهای با شیب، احتمال رسوب‌گذاری ذرات معلق در نقاط پایین‌دست بیشتر می‌شود.</li>\n<li><strong>ضخامت جداره (W):</strong> ضخامت لوله با کلاس فشار کاری ( ) مرتبط است. هرچه اختلاف ارتفاع (فشار ایستایی) بین منبع آب و محل مصرف بیشتر باشد، فشار در نقاط پایین‌دست بالاتر خواهد رفت. برای مزارع دارای شیب، استفاده از لوله‌هایی با کلاس فشار بالاتر توصیه می‌شود تا از پاره شدن جداره در اثر فشار زیاد جلوگیری شود. دقت داشته باشید که ضخامت یکسان برای همه شرایط مناسب نیست و باید بر اساس فشار ایستایی محاسبه‌شده انتخاب گردد.</li>\n</ul>\n\n<table border="1" cellpadding="5" style="border-collapse: collapse; width: 100%;">\n<thead>\n<tr>\n<th style="border: 1px solid #000; padding: 8px; background-color: #f2f2f2;">سایز (انچ)</th>\n<th style="border: 1px solid #000; padding: 8px; background-color: #f2f2f2;">کاربرد رایج</th>\n<th style="border: 1px solid #000; padding: 8px; background-color: #f2f2f2;">نکات فنی</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td style="border: 1px solid #000; padding: 8px;">۲ تا ۴</td>\n<td style="border: 1px solid #000; padding: 8px;">مزارع کوچک یا فرعی با دبی کم</td>\n<td style="border: 1px solid #000; padding: 8px;">مناسب برای اختلاف ارتفاع کمتر</td>\n</tr>\n<tr>\n<td style="border: 1px solid #000; padding: 8px;">۵ تا ۸</td>\n<td style="border: 1px solid #000; padding: 8px;">خط اصلی مزارع متوسط</td>\n<td style="border: 1px solid #000; padding: 8px;">تعادل مناسب بین وزن و ظرفیت</td>\n</tr>\n<tr>\n<td style="border: 1px solid #000; padding: 8px;">۱۰ و بیشتر</td>\n<td style="border: 1px solid #000; padding: 8px;">شبکه‌های اصلی با دبی بالا</td>\n<td style="border: 1px solid #000; padding: 8px;">نیازمند بررسی دقیق فشار و پمپاژ</td>\n</tr>\n</tbody>\n</table>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-city-generated/لوله-نخی-تاشو-کلیبر-آذربایجان-شرقی-looleh-nakhi-tashoo-انتخاب-محصول.webp" alt="انتخاب نوار تیپ متناسب با مزرعه کلیبر"/><figcaption>انتخاب نوار تیپ متناسب با مزرعه کلیبر</figcaption></figure>\n\n\n<p>توجه داشته باشید که لوله‌های نخی و تاشو معمولاً برای خطوط انتقالی اصلی فرعی یا شبکه‌های متحرک طراحی شده‌اند و جایگزین کامل لوله‌های سخت برای خطوط ثابت زیرزمینی سنگین نیستند. در صورت نیاز به خطوط دائمی با مقاومت بسیار بالا در برابر فشار و فشار مکانیکی، طراحی متخصص باید انجام شود. همچنین، لوله‌های تاشو به عنوان لاین اصلی، می‌توانند نوارهای فرعی را تغذیه کنند که در این حالت، سازگاری کیفیت آب با جنس سیستم فیلتراسیون باید بررسی شود.</p>\n\n<h2>انتخاب جنس مواد و مقاومت در برابر شرایط اقلیمی</h2>\n<p>مقاومت مواد تشکیل‌دهنده لوله در برابر عوامل محیطی، به‌ویژه تابش فرابنفش (UV) و نوسانات دما، تعیین‌کننده طول عمر سیستم آبیاری است. اگرچه جزئیات دقیق اقلیمی هر روستا یا محله متغیر است، اما در نظر گرفتن شرایط کلی منطقه برای انتخاب جنس مناسب ضروری است. لوله‌های بافت از جنس مش با پوشش‌های مختلف تولید می‌شوند و هر کدام ویژگی‌های مشخصی دارند.</p>\n<p class="navar-related-inline">برای تکمیل این بخش، راهنمای <a href="https://navar-abyari.ir/acf-field/field_62559b0e687d1/">k2</a> را نیز ببینید.</p>\n<ol>\n<li><strong>پوشش پلی‌اورتان ():</strong> این جنس در بسیاری از لوله‌های تاشو کشاورزی کاربرد دارد. پلی‌اورتان مقاومت خوبی در برابر UV و اصطکاک دارد، اما در مقایسه با برخی جنس‌های دیگر، ممکن است در شرایط خاص سریع‌تر فرسایش پیدا کند. دوام دقیق آن بستگی به دقت در نگهداری و شستشو دارد.</li>\n<li><strong>پوشش پلی‌اتیلن یا کامپوزیتی:</strong> برخی مدل‌های پیشرفته‌تر از پوشش‌های ترکیبی استفاده می‌کنند که دوام بیشتری در برابر شکست خستگی و پاره شدن دارند. هنگام خرید، حتماً برچسب فنی () محصول را بررسی کنید تا از جنس پوشش و کلاس فشاری آن مطمئن شوید.</li>\n<li><strong>جنس نوار فرعی:</strong> در صورت اتصال نوار فرعی به این لوله‌ها، توجه کنید که جنس رایج نوار قطره‌ای پلی‌اتیلن است. جنس‌های شکننده در دماهای بسیار پایین برای مناطق سردسیری مناسب نیستند. بنابراین، اگر در زمستان از سیستم استفاده می‌کنید، جنس پوشش لوله اصلی و نوار فرعی را متناسب با حداقل دمای محلی انتخاب کنید.</li>\n</ol>\n<p>برای استفاده در دمای زمستانی، توصیه می‌شود از لوله‌هایی استفاده کنید که در دیتاشیت سازنده، مقاومت در برابر دمای پایین ذکر شده باشد. یک نکته ایمنی بسیار مهم این است که هیچ‌گاه لوله خالی را در معرض سرما قرار ندهید. قرار دادن لوله خالی در شب‌های سرد می‌تواند باعث سفت شدن و ترک‌خوردن جداره شود. همیشه پس از اتمام آبیاری، لوله را خالی کرده و در صورت نیاز به ذخیره‌سازی در هوای سرد، آن را در فضای بسته یا دارای دمای مناسب قرار دهید.</p>\n\n<h2>فشار، فیلتراسیون و مدیریت کیفیت آب</h2>\n<p>یکی از چالش‌های اصلی بهره‌برداری از سیستم‌های آبیاری با لوله تاشو، ورود آلودگی‌ها به سیستم است. زیرا این لوله‌ها معمولاً در فضای باز قرار دارند و در طول مسیر با محیط تماس پیدا می‌کنند. گرد و غبار، برگ‌های خشک و ذرات معلق می‌توانند وارد لوله شوند. این ذرات نه‌تنها می‌توانند به فیلترهای سیستم آسیب برسانند، بلکه باعث انسداد نوارهای قطره‌ای فرعی می‌شوند. بنابراین، فیلتراسیون صحیح قبل از ورود آب به لوله اصلی ضروری است.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-city-generated/لوله-نخی-تاشو-کلیبر-آذربایجان-شرقی-looleh-nakhi-tashoo-جزئیات-فنی.webp" alt="فیلتر و تنظیم فشار سیستم آبیاری قطره‌ای در کلیبر"/><figcaption>فیلتر و تنظیم فشار سیستم آبیاری قطره‌ای در کلیبر</figcaption></figure>\n\n<p>نصب سیستم فیلتراسیون مناسب (مانند فیلتر ماسه‌ای، گلوله‌ای یا دیسکی) بسته به کیفیت آب منطقه، توصیه می‌شود. نوع فیلتر باید بر اساس میزان رسوب و ذرات معلق موجود در آب محل تعیین شود و لزوماً برای همه مزارع یکسان نیست. همچنین، کنترل فشار در ابتدای خط با یک گیج فشار به شما کمک می‌کند تا اطمینان حاصل کنید فشار وارد لوله در حد مجاز است. اگر فشار در انتهای لوله به دلیل طول زیاد یا شیب بالا از حد تحمل لوله فراتر رفت، ممکن است نیاز به نصب شیر تنظیم فشار در نقاط پایین‌دست باشد. این اقدام از پاره شدن لوله در اثر فشار ایستایی زیاد جلوگیری می‌کند. دقت داشته باشید که انتخاب نوع فیلتر و فشار کاری سیستم، باید بر اساس دیتاشیت سازنده لوله و تحلیل کیفیت آب انجام شود.</p>\n\n<h2>راهنمای گام به گام نصب لوله نخی و تاشو</h2>\n<p>نصب صحیح نقش تعیین‌کننده‌ای در افزایش عمر مفید لوله ایفا می‌کند. پیروی از مراحل زیر، از پارگی زودرس و نشتی جلوگیری می‌کند:</p>\n<p class="navar-related-inline">مطالعه مطلب <a href="https://navar-abyari.ir/%D9%84%D9%88%D9%84%D9%87-%D8%AA%D8%A7%D8%B4%D9%88-%DA%A9%D8%B4%D8%A7%D9%88%D8%B1%D8%B2%DB%8C/">D984D988D984D987 D8AAD8A7D8B4D988 DAA9D8B4D8A7D988D8B1D8B2DB8C</a> می‌تواند جزئیات بیشتری در اختیارتان بگذارد.</p>\n<ol>\n<li><strong>باز کردن صحیح لوله:</strong> لوله را از رول به‌صورت پیچ‌خورده نکشید تا گره ایجاد نشود. بهتر است از یک کمک‌کار استفاده کنید تا لوله به‌صورت موازی و بدون کشش مکانیکی از رول خارج شود.</li>\n<li><strong>اتصال ورودی:</strong> از قطعات اتصال فلزی باکیفیت (کاپلینگ) استفاده کنید. حلقه‌های نگهدارنده را محکم ببندید تا نشتی آب در محل اتصال رخ ندهد. اتصالات باید دقیقاً منطبق با اندازه لوله باشند.</li>\n<li><strong>پخش روی زمین:</strong> لوله را بر روی سطح صاف و تمیز قرار دهید. از قرار دادن لوله روی سنگ‌ها، شاخه‌های خشک و سطوح تیز خودداری کنید، زیرا این موارد باعث پارگی زودرس جداره از درون یا بیرون می‌شوند. در نواحی با شیب، استفاده از محبوس‌های مناسب برای تثبیت لوله ضروری است.</li>\n<li><strong>آب‌گیری اولیه:</strong> آب را به‌آرامی وارد سیستم کنید تا حباب‌های هوا خارج شوند. هرگز سیستم را یکجا با فشار کامل فعال نکنید، زیرا شوک فشاری می‌تواند به اتصالات آسیب برساند.</li>\n<li><strong>اتصال نوار فرعی:</strong> در صورت اتصال نوار قطره‌ای، اتصالات باید به‌صورت مایل و بدون ایجاد فشار مکانیکی روی جداره لوله اصلی انجام شود. نوار فرعی باید آزادانه جریان داشته باشد.</li>\n</ol>\n<p>برای اطمینان از چیدمان صحیح اتصالات و پیکربندی سیستم، پیروی از دستورالعمل‌های تولیدکننده لوله توصیه می‌شود. طراحی سیستم باید متناسب با شیب زمین، دبی مطلوب و نوع محصول انتخاب شود.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-city-generated/لوله-نخی-تاشو-کلیبر-آذربایجان-شرقی-looleh-nakhi-tashoo-نصب-مزرعه.webp" alt="نصب صحیح نوار آبیاری در ردیف‌های کشت کلیبر"/><figcaption>نصب صحیح نوار آبیاری در ردیف‌های کشت کلیبر</figcaption></figure>\n\n\n<h2>نگهداری و عیوب رایج در سیستم‌های آبیاری با لوله تاشو</h2>\n<p>عمر مفید لوله‌های نخی و تاشو بستگی مستقیمی به نحوه نگهداری دارد. با رعایت اصول زیر، می‌توان از خرابی‌های پرهزینه جلوگیری کرد:</p>\n<ul>\n<li><strong>شستشوی دوره‌ای:</strong> پس از پایان هر فصل یا هر بار استفاده طولانی، لوله را با آب تمیز بشویید تا رسوبات و ذرات معلق خارج شوند. سپس لوله را باز نموده و بپیچید تا خشک شود.</li>\n<li><strong>ذخیره‌سازی صحیح:</strong> لوله‌های تاشو را بپیچید، نه تا کنید. تا کردن باعث ایجاد شکستگی‌های خستگی ( ) در سازه مشی لوله می‌شود. آن‌ها را در سایه و دور از تابش مستقیم UV ذخیره کنید. بهترین مکان برای ذخیره، انباری با تهویه مناسب و دمای معتدل است.</li>\n<li><strong>اتصال به نوار فرعی:</strong> اگر نوار قطره‌ای را به‌عنوان لاین فرعی استفاده می‌کنید، اتصالات را در محلی انجام دهید که نوار بتواند آزادانه جریان داشته باشد. توجه به دبی مناسب هر قطره‌چکان برای جلوگیری از خیس‌شدگی بیش از حد ریشه گیاهان ضروری است.</li>\n</ul>\n<p class="navar-related-inline">در همین زمینه، مقاله <a href="https://navar-abyari.ir/zanjan/%d9%86%d9%88%d8%a7%d8%b1-%d8%aa%db%8c%d9%be-%d8%a2%d8%a8-%d8%a8%d8%b1-%d9%82%db%8c%d9%85%d8%aa-%d8%ae%d8%b1%db%8c%d8%af-%d8%b1%d9%88%d9%84-1000-%d9%85%d8%aa%d8%b1%db%8c/">خرید نوار تیپ آب بر | لیست قیمت امروز کارخانه AFP</a> نیز پیشنهاد می‌شود.</p>\n<p>مشکلات رایجی که در این سیستم‌ها مشاهده می‌شود عبارتند از: افت فشار در انتهای خط، نشتی از درزهای اتصالات، و پاره شدن لوله در نقاطی که با وسایل تیز تماس داشته‌اند. برای جلوگیری از نشتی، از اتصالات استاندارد استفاده کنید. همچنین، هرگز لوله را با فشار هوا ببارید؛ فقط با آب عملیات را انجام دهید، زیرا هوا ممکن است باعث ناپایداری فشار و آسیب به سازه لوله شود.</p>\n\n<h2>راهنمای خرید از فروشگاه‌های معتبر</h2>\n<p>هنگام خرید لوله نخی و تاشو، به دنبال نشان‌های استاندارد ملی و گواهی‌های کیفیت باشید. لوله‌های بدون برچسب مشخصات فنی، معمولاً از مواد بازیافتی با کیفیت پایین ساخته شده‌اند و دوام قابل اتکایی ندارند. بررسی دیتاشیت محصول، شامل ضخامت بافت، نوع پوشش و کلاس فشار، پیش از خرید امری حیاتی است.</p>\n<p>مواردی که هنگام بازرسی فیزیکی لوله باید بررسی شوند:</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-city-generated/لوله-نخی-تاشو-کلیبر-آذربایجان-شرقی-looleh-nakhi-tashoo-اتصال-و-کاربرد.webp" alt="بازرسی و نگهداری نوار آبیاری در مزرعه کلیبر"/><figcaption>بازرسی و نگهداری نوار آبیاری در مزرعه کلیبر</figcaption></figure>\n\n<ol>\n<li><strong>ضخامت بافت:</strong> لوله‌های استاندارد معمولاً دارای بافت ۲۲ یا ۳۶ تخته مش هستند. لوله‌های بافت نازک‌تر (مانند ۱۲ تخته) فقط برای کاربردهای سبک و موقت مناسب‌اند و دوام پایایی ندارند.</li>\n<li><strong>جنس پوشش:</strong> پوشش خارجی باید نازک، یکنواخت و بدون چین و چروک باشد. از خرید لوله‌هایی با پوشش نامتقارن یا رنگ‌های نامتجانس که نشانه عدم کنترل کیفیت است، پرهیز کنید.</li>\n<li><strong>اتصالات:</strong> قطعات اتصال فلزی باید از جنس گالوانیزه باکیفیت یا استیل باشند تا در برابر رطوبت و مواد معدنی موجود در آب مقاومت کنند.</li>\n</ol>\n<p>برای مشاوره تخصصی در انتخاب سایز لوله متناسب با دبی آب و شرایط زمین، حتماً با متخصصان آبیاری مشورت کنید. دقت در انتخاب اولیه، هزینه‌های تعمیر و تعویض در آینده را کاهش می‌دهد.</p>\n<p class="navar-related-inline">برای مقایسه و تصمیم‌گیری بهتر، مطلب <a href="https://navar-abyari.ir/%d8%b9%d9%85%d9%84%da%a9%d8%b1%d8%af-%d9%be%db%8c%d8%a7%d8%b2-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/">عملکرد پیاز در هکتار: راهکارهای افزایش تناژ و سودآوری</a> را بخوانید.</p>\n\n<h2>بهره‌وری بیشتر و نکات تکمیلی فنی</h2>\n<p>انتخاب لوله تنها بخشی از بهینه‌سازی سیستم آبیاری است. اگر از لوله‌های تاشو استفاده می‌کنید، می‌توانید از یک ترکیب بهینه بهره ببرید: استفاده از لوله‌های ثابت برای خطوط اصلی که نیاز به جابجایی ندارند، و استفاده از لوله تاشو برای خطوط فرعی که نیاز به تغییر موقعیت یا دسترسی آسان دارند. این ترکیب، تعادل خوبی بین دوام بلندمدت و انعطاف‌پذیری ایجاد می‌کند. همچنین، آبیاری قطره‌ای با نوار فرعی به عنوان روش نهایی تحویل آب، به شرطی که از فیلتراسیون مناسب و کیفیت آب مطلوب برخوردار باشد، می‌تواند راندمان آبیاری را افزایش دهد.</p>\n<p>توجه به فاصله قطره‌چکان بسیار مهم است. برای بسیاری از کشت‌های ردیفی، نوار فرعی با فاصله ۲۰ سانتی‌متر کاربرد دارد، اما برای درختان یا کشت‌های بافاصله بیشتر، استفاده از فواصل ۴۰ یا ۶۰ سانتی‌متر ممکن است مناسب‌تر باشد. انتخاب نهایی فاصله، نوع پوشش‌دحراری و کیفیت آب را به دقت بررسی کنید. اسیدشویی (در صورت نیاز برای پیشگیری از رسوب)، فقط باید با بررسی دقیق کیفیت آب، دستور سازنده نوار فرعی و نظارت متخصص انجام شود تا از آسیب به سیستم جلوگیری شود.</p>\n\n<p>برای دریافت مشاوره یا سفارش محصول، از طریق واتساپ با ما در ارتباط باشید.</p><p>برای دریافت مشاوره یا سفارش محصول، از طریق <a href="https://wa.me/989134922013">واتساپ با ما در ارتباط باشید</a>.</p><p>برای دریافت مشاوره یا سفارش محصول، از طریق <a href="https://wa.me/989134922013">واتساپ با ما در ارتباط باشید</a>.</p><p>برای دریافت مشاوره یا سفارش محصول، از طریق <a href="https://wa.me/989134922013">واتساپ با ما در ارتباط باشید</a>.</p><h3 id="faq">پرسش‌های متداول درباره لوله نخی و تاشو در کلیبر</h3><details><summary>برای انتخاب سایز لوله نخی و تاشو چه مواردی بررسی شود؟</summary>دبی موردنیاز، طول مسیر، اختلاف ارتفاع، فشار پمپ، نوع اتصال و دیتاشیت سازنده باید پیش از خرید بررسی شود.<br><br></details><details><summary>فشار کار لوله تاشو چگونه تعیین می‌شود؟</summary>فشار مجاز باید از روی مشخصات همان محصول انتخاب شود و فشار واقعی ابتدا و انتهای مسیر نیز هنگام راه‌اندازی اندازه‌گیری شود.<br><br></details><details><summary>چطور از لوله نخی در مزرعه نگهداری کنیم؟</summary>از کشیدن روی لبه تیز، تاخوردگی شدید و عبور ماشین‌آلات جلوگیری کنید و پس از تخلیه آب، لوله را تمیز و دور از تابش طولانی نگه دارید.<br><br></details>','خرید لوله نخی و تاشو در کلیبر','راهنمای تخصصی خرید لوله نخی و تاشو در کلیبر. اصول انتخاب سایز، جنس مناسب، نصب صحیح و نگهداری برای بهره‌وری حداکثری آب در مزارع.','publish','closed','closed','کلیبر-آذربایجان-شرقی-looleh-nakhi-tashoo',NOW(),UTC_TIMESTAMP(),0,'',0,'east_azarbaijan','',0 WHERE @created_post=1;
